fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // If there are fewer than 2 elements, nothing to insert.
    if n <= 1 {
        return numbers;
    }

    // Prepare a result vector of the exact required capacity.
    let mut result = Vec::with_capacity(2 * n - 1);

    // Iterate over the input, inserting delimiter between elements.
    let mut iter = numbers.into_iter();
    if let Some(first) = iter.next() {
        result.push(first);
        for num in iter {
            result.push(delimiter);
            result.push(num);
        }
    }

    result
}

